SELECT id, store_name, region, NTILE(4) OVER (ORDER BY sqft ASC, id ASC) AS sqft_bucket, LEAD(sqft, 2) OVER (PARTITION BY city ORDER BY sqft ASC, id ASC) AS next_sqft, PERCENT_RANK() OVER w_running AS sqft_percent_rank, ROW_NUMBER() OVER (PARTITION BY region, city ORDER BY sqft ASC, id ASC) AS row_seq FROM stores WINDOW w_running AS (PARTITION BY city ORDER BY sqft DESC NULLS LAST);
